import React, { useState, useEffect } from 'react';
import { useAuth } from '../context/AuthContext';
import api from '../services/api';
import toast from 'react-hot-toast';
import { FiUser, FiPhone, FiLock, FiSave, FiEdit2, FiX } from 'react-icons/fi';

const Profile = () => {
    const { user, logout } = useAuth();
    const [loading, setLoading] = useState(false);
    const [editMode, setEditMode] = useState(false);
    const [formData, setFormData] = useState({
        name: '',
        phone: '',
        currentPassword: '',
        newPassword: '',
        confirmPassword: ''
    });
    const [error, setError] = useState('');

    useEffect(() => {
        if (user) {
            setFormData({
                ...formData,
                name: user.name,
                phone: user.phone
            });
        }
    }, [user]);

    // Validar número de telefone angolano
    const validateAngolaPhone = (phone) => {
        const cleanPhone = phone.replace(/\D/g, '');
        if (cleanPhone.length === 9 && cleanPhone.startsWith('9')) return true;
        if (cleanPhone.length === 12 && cleanPhone.startsWith('2449')) return true;
        return false;
    };

    const handleChange = (e) => {
        setFormData({ ...formData, [e.target.name]: e.target.value });
        setError('');
    };

    const handlePhoneChange = (e) => {
        let value = e.target.value.replace(/\D/g, '');
        if (value.length > 9) value = value.slice(0, 9);
        setFormData({ ...formData, phone: value });
    };

    const handleSave = async () => {
        setError('');
        
        // Validar nome
        if (formData.name.length < 3) {
            setError('Nome deve ter pelo menos 3 caracteres');
            return;
        }
        
        // Validar telefone se foi alterado
        if (formData.phone !== user?.phone && !validateAngolaPhone(formData.phone)) {
            setError('Número de telefone inválido. Use um número angolano válido (ex: 923456789)');
            return;
        }
        
        // Validar senha se for alterar
        if (formData.newPassword) {
            if (formData.newPassword.length < 6) {
                setError('A nova senha deve ter pelo menos 6 caracteres');
                return;
            }
            if (formData.newPassword !== formData.confirmPassword) {
                setError('As novas senhas não coincidem');
                return;
            }
            if (!formData.currentPassword) {
                setError('Digite sua senha atual para confirmar a alteração');
                return;
            }
        }
        
        setLoading(true);
        
        try {
            // Atualizar perfil
            const updateData = {
                name: formData.name,
                phone: formData.phone
            };
            
            if (formData.newPassword) {
                updateData.currentPassword = formData.currentPassword;
                updateData.newPassword = formData.newPassword;
            }
            
            const response = await api.put('/auth/profile', updateData);
            
            if (response.data.success) {
                toast.success('Perfil atualizado com sucesso!');
                // Atualizar dados do usuário
                user.name = formData.name;
                user.phone = formData.phone;
                localStorage.setItem('techmarket_user', JSON.stringify(user));
                setEditMode(false);
                setFormData({
                    ...formData,
                    currentPassword: '',
                    newPassword: '',
                    confirmPassword: ''
                });
            }
        } catch (error) {
            toast.error(error.response?.data?.error || 'Erro ao atualizar perfil');
        } finally {
            setLoading(false);
        }
    };

    const handleCancel = () => {
        setFormData({
            name: user?.name || '',
            phone: user?.phone || '',
            currentPassword: '',
            newPassword: '',
            confirmPassword: ''
        });
        setEditMode(false);
        setError('');
    };

    if (!user) return null;

    return (
        <div className="max-w-2xl mx-auto">
            <div className="bg-white rounded-xl shadow-md overflow-hidden">
                {/* Header */}
                <div className="bg-gradient-to-r from-primary-600 to-primary-800 text-white p-6">
                    <div className="flex items-center justify-between">
                        <div>
                            <h1 className="text-2xl font-bold">Meu Perfil</h1>
                            <p className="opacity-90 mt-1">Gerencie suas informações pessoais</p>
                        </div>
                        {!editMode && (
                            <button
                                onClick={() => setEditMode(true)}
                                className="bg-white text-primary-600 px-4 py-2 rounded-lg flex items-center gap-2 hover:bg-gray-100 transition"
                            >
                                <FiEdit2 /> Editar Perfil
                            </button>
                        )}
                    </div>
                </div>
                
                {/* Conteúdo */}
                <div className="p-6">
                    {error && (
                        <div className="bg-red-50 text-red-600 p-3 rounded-lg mb-4 text-sm">
                            {error}
                        </div>
                    )}
                    
                    <div className="space-y-4">
                        {/* Nome */}
                        <div>
                            <label className="block text-gray-700 mb-2">
                                <FiUser className="inline mr-2" /> Nome completo
                            </label>
                            {editMode ? (
                                <input
                                    type="text"
                                    name="name"
                                    value={formData.name}
                                    onChange={handleChange}
                                    className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:outline-none focus:border-primary-600"
                                    placeholder="Seu nome"
                                />
                            ) : (
                                <div className="bg-gray-50 px-3 py-2 rounded-lg text-gray-700">
                                    {user.name}
                                </div>
                            )}
                        </div>
                        
                        {/* Telefone */}
                        <div>
                            <label className="block text-gray-700 mb-2">
                                <FiPhone className="inline mr-2" /> Número de telefone
                            </label>
                            {editMode ? (
                                <div>
                                    <input
                                        type="tel"
                                        name="phone"
                                        value={formData.phone}
                                        onChange={handlePhoneChange}
                                        className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:outline-none focus:border-primary-600"
                                        placeholder="923456789"
                                    />
                                    <p className="text-xs text-gray-500 mt-1">
                                        Digite apenas os números. Ex: 923456789
                                    </p>
                                </div>
                            ) : (
                                <div className="bg-gray-50 px-3 py-2 rounded-lg text-gray-700">
                                    {user.phone}
                                </div>
                            )}
                        </div>
                        
                        {/* Tipo de conta */}
                        <div>
                            <label className="block text-gray-700 mb-2">
                                Tipo de conta
                            </label>
                            <div className="bg-gray-50 px-3 py-2 rounded-lg text-gray-700">
                                {user.type === 'vendedor' ? '👤 Vendedor' : '🛍️ Comprador'}
                            </div>
                        </div>
                        
                        {/* Seção de alteração de senha (só no modo edição) */}
                        {editMode && (
                            <div className="border-t pt-4 mt-4">
                                <h3 className="font-semibold text-gray-800 mb-3">Alterar senha</h3>
                                <div className="space-y-3">
                                    <div>
                                        <label className="block text-gray-700 mb-2">Senha atual</label>
                                        <div className="relative">
                                            <FiLock className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400" />
                                            <input
                                                type="password"
                                                name="currentPassword"
                                                value={formData.currentPassword}
                                                onChange={handleChange}
                                                placeholder="Digite sua senha atual"
                                                className="w-full pl-10 pr-3 py-2 border border-gray-300 rounded-lg focus:outline-none focus:border-primary-600"
                                            />
                                        </div>
                                    </div>
                                    <div>
                                        <label className="block text-gray-700 mb-2">Nova senha</label>
                                        <div className="relative">
                                            <FiLock className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400" />
                                            <input
                                                type="password"
                                                name="newPassword"
                                                value={formData.newPassword}
                                                onChange={handleChange}
                                                placeholder="Mínimo 6 caracteres"
                                                className="w-full pl-10 pr-3 py-2 border border-gray-300 rounded-lg focus:outline-none focus:border-primary-600"
                                            />
                                        </div>
                                    </div>
                                    <div>
                                        <label className="block text-gray-700 mb-2">Confirmar nova senha</label>
                                        <div className="relative">
                                            <FiLock className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400" />
                                            <input
                                                type="password"
                                                name="confirmPassword"
                                                value={formData.confirmPassword}
                                                onChange={handleChange}
                                                placeholder="Digite a nova senha novamente"
                                                className="w-full pl-10 pr-3 py-2 border border-gray-300 rounded-lg focus:outline-none focus:border-primary-600"
                                            />
                                        </div>
                                    </div>
                                </div>
                            </div>
                        )}
                        
                        {/* Botões de ação (modo edição) */}
                        {editMode && (
                            <div className="flex gap-3 mt-6">
                                <button
                                    onClick={handleSave}
                                    disabled={loading}
                                    className="flex-1 bg-primary-600 text-white py-2 rounded-lg hover:bg-primary-700 transition flex items-center justify-center gap-2 disabled:opacity-50"
                                >
                                    <FiSave /> {loading ? 'Salvando...' : 'Salvar alterações'}
                                </button>
                                <button
                                    onClick={handleCancel}
                                    className="flex-1 bg-gray-200 text-gray-700 py-2 rounded-lg hover:bg-gray-300 transition flex items-center justify-center gap-2"
                                >
                                    <FiX /> Cancelar
                                </button>
                            </div>
                        )}
                        
                        {/* Informações adicionais */}
                        <div className="border-t pt-4 mt-4 text-sm text-gray-500">
                            <p>📅 Conta criada em: {new Date(user.createdAt).toLocaleDateString('pt-BR')}</p>
                            {user.type === 'vendedor' && (
                                <p className="mt-1">📊 Total de anúncios: {user.totalProducts || 0}</p>
                            )}
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
};

export default Profile;
